package com.phoenix.business.service;
import com.phoenix.business.domain.*; import com.phoenix.business.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class AuditService {private final AuditLogRepository logs;private final UserRepository users;@Transactional public void record(String action,String type,Object id,String summary){String name=SecurityContextHolder.getContext().getAuthentication()==null?"SYSTEM":SecurityContextHolder.getContext().getAuthentication().getName();AuditLog l=new AuditLog();l.setAction(action);l.setEntityType(type);l.setEntityId(id==null?null:String.valueOf(id));l.setActorUsername(name);users.findByUsernameIgnoreCase(name).ifPresent(l::setActor);l.setSummary(sanitize(summary));logs.save(l);} private String sanitize(String s){return s==null?null:s.replaceAll("(?i)(password|token|secret)\\s*[:=]\\s*\\S+","$1=[REDACTED]");}}
